import type {
  STTProvider,
  STTStream,
  StreamEvents,
  StreamOptions,
} from './provider.js';

export class SttReconnectError extends Error {
  readonly code = 'STT_RECONNECT_FAILED';
  constructor(attempts: number, cause?: Error) {
    super(
      `STT connection dropped and could not be re-established after ${attempts} attempts` +
        (cause ? `: ${cause.message}` : ''),
    );
    this.name = 'SttReconnectError';
  }
}

export interface ReconnectOptions {
  maxAttempts?: number;
  baseDelayMs?: number;
  maxPendingAudio?: number;
  random?: () => number;
}

const DEFAULT_MAX_ATTEMPTS = 5;
const DEFAULT_BASE_DELAY_MS = 1_000;
const DEFAULT_MAX_PENDING_AUDIO = 256;

// Mid-session resilience: an unexpectedly dropped provider socket must not
// kill the session. A close or error while the stream is live starts a
// bounded retry sequence (exponential backoff with equal jitter); audio that
// arrives while down is buffered and flushed into the replacement stream.
// A deliberate close() never retries.
export function withReconnect(
  provider: STTProvider,
  options: ReconnectOptions = {},
): STTProvider {
  const maxAttempts = options.maxAttempts ?? DEFAULT_MAX_ATTEMPTS;
  const baseDelayMs = options.baseDelayMs ?? DEFAULT_BASE_DELAY_MS;
  const maxPending = options.maxPendingAudio ?? DEFAULT_MAX_PENDING_AUDIO;
  const random = options.random ?? Math.random;

  return {
    name: provider.name,
    supports_diarization: provider.supports_diarization,
    async start_stream(
      opts: StreamOptions,
      events: StreamEvents,
    ): Promise<STTStream> {
      let closed = false; // close() called: terminal, never retry
      let closeNotified = false; // events.onClose already delivered
      let reconnecting = false; // a drop is being retried right now
      let failedAttempts = 0;
      let timer: ReturnType<typeof setTimeout> | undefined;
      let pending: Buffer[] = [];
      let lastErr: Error | undefined;
      let inner: STTStream;

      const notifyClose = () => {
        if (closeNotified) return;
        closeNotified = true;
        events.onClose?.();
      };

      const giveUp = () => {
        reconnecting = false;
        pending = [];
        events.onError(new SttReconnectError(maxAttempts, lastErr));
        notifyClose();
      };

      const scheduleRetry = () => {
        if (closed) return;
        if (failedAttempts >= maxAttempts) {
          giveUp();
          return;
        }
        const nominal = baseDelayMs * 2 ** failedAttempts;
        timer = setTimeout(
          () => {
            timer = undefined;
            void attemptReconnect();
          },
          Math.round(nominal / 2 + random() * (nominal / 2)),
        );
      };

      const attemptReconnect = async () => {
        if (closed) return;
        try {
          const stream = await provider.start_stream(opts, innerEvents);
          if (closed) {
            stream.close();
            return;
          }
          inner = stream;
          reconnecting = false;
          failedAttempts = 0;
          events.onReconnect?.();
          const buffered = pending;
          pending = [];
          try {
            for (const chunk of buffered) inner.send_audio(chunk);
          } catch (err) {
            lastErr = toError(err);
            onDrop();
          }
        } catch (err) {
          lastErr = toError(err);
          failedAttempts += 1;
          scheduleRetry();
        }
      };

      const onDrop = () => {
        if (closed || reconnecting || closeNotified) return;
        reconnecting = true;
        failedAttempts = 0;
        scheduleRetry();
      };

      const innerEvents: StreamEvents = {
        onPartial: (seg) => events.onPartial(seg),
        onFinal: (seg) => events.onFinal(seg),
        // Errors imply a broken transport: they enter the retry sequence
        // instead of being forwarded, so the client only hears about the
        // one unrecoverable failure after retries are exhausted.
        onError: (err) => {
          lastErr = err;
          onDrop();
        },
        onClose: () => {
          if (closed) {
            notifyClose();
            return;
          }
          onDrop();
        },
      };

      inner = await provider.start_stream(opts, innerEvents);

      return {
        send_audio: (chunk: Buffer) => {
          if (closed) return;
          if (reconnecting) {
            if (pending.length < maxPending) pending.push(chunk);
            return;
          }
          inner.send_audio(chunk);
        },
        close: () => {
          if (closed) return;
          closed = true;
          if (timer) clearTimeout(timer);
          pending = [];
          try {
            inner.close();
          } catch {
            // already closed
          }
          notifyClose();
        },
      };
    },
  };
}

function toError(err: unknown): Error {
  return err instanceof Error ? err : new Error(String(err));
}

