import { EventEmitter } from 'node:events';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { SttReconnectError, withReconnect } from './reconnect.js';
import type {
  STTProvider,
  STTStream,
  StreamEvents,
  StreamOptions,
} from './provider.js';

// Mocked socket level: FakeStream stands in for the provider transport and
// can be dropped or errored on demand; FakeProvider counts dial attempts.
// No provider keys or network are involved.
class FakeStream implements STTStream {
  audio: Buffer[] = [];
  closed = false;
  constructor(private readonly events: StreamEvents) {}
  send_audio(chunk: Buffer): void {
    this.audio.push(chunk);
  }
  close(): void {
    if (this.closed) return;
    this.closed = true;
    this.events.onClose?.();
  }
  drop(): void {
    this.events.onClose?.();
  }
  fail(err: Error): void {
    this.events.onError(err);
  }
}

class FakeProvider implements STTProvider {
  readonly name = 'fake';
  readonly supports_diarization = false;
  streams: FakeStream[] = [];
  failuresLeft = 0;
  async start_stream(
    _opts: StreamOptions,
    events: StreamEvents,
  ): Promise<STTStream> {
    if (this.failuresLeft > 0) {
      this.failuresLeft -= 1;
      throw new Error('connect failed');
    }
    const stream = new FakeStream(events);
    this.streams.push(stream);
    return stream;
  }
  get startCount(): number {
    return this.streams.length;
  }
}

function stubbed() {
  const partials: string[] = [];
  const finals: string[] = [];
  const errors: Error[] = [];
  let closedCount = 0;
  let reconnectCount = 0;
  const events: StreamEvents = {
    onPartial: (s) => partials.push(s.text),
    onFinal: (s) => finals.push(s.text),
    onError: (e) => errors.push(e),
    onClose: () => {
      closedCount += 1;
    },
    onReconnect: () => {
      reconnectCount += 1;
    },
  };
  return {
    events,
    partials,
    finals,
    errors,
    get closedCount() {
      return closedCount;
    },
    get reconnectCount() {
      return reconnectCount;
    },
  };
}

describe('withReconnect', () => {
  beforeEach(() => vi.useFakeTimers());
  afterEach(() => vi.useRealTimers());

  it('reconnects after an unexpected close and flushes buffered audio', async () => {
    const provider = new FakeProvider();
